result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_varint.py", "content": "import random

import pytest

from varint import (
    VarintError,
    decode_svarint,
    decode_uvarint,
    encode_svarint,
    encode_uvarint,
    zigzag_decode,
    zigzag_encode,
)


class TestKnownVectors:
    @pytest.mark.parametrize(
        ("value", "encoded"),
        [
            (0, b"\x00"),
            (127, b"\x7f"),
            (128, b"\x80\x01"),
            (300, b"\xac\x02"),
        ],
    )
    def test_encode(self, value, encoded):
        assert encode_uvarint(value) == encoded

    @pytest.mark.parametrize(
        ("value", "encoded"),
        [
            (0, b"\x00"),
            (127, b"\x7f"),
            (128, b"\x80\x01"),
            (300, b"\xac\x02"),
        ],
    )
    def test_decode(self, value, encoded):
        assert decode_uvarint(encoded) == (value, len(encoded))

    def test_max_uint64(self):
        expected = b"\xff" * 9 + b"\x01"
        assert encode_uvarint(2**64 - 1) == expected
        assert len(expected) == 10
        assert decode_uvarint(expected) == (2**64 - 1, 10)


class TestRoundTrip:
    @pytest.mark.parametrize("k", range(0, 65))
    def test_boundaries(self, k):
        for v in {2**k, 2**k - 1} & set(range(2**64)):
            assert decode_uvarint(encode_uvarint(v)) == (v, len(encode_uvarint(v)))

    def test_random_5000(self):
        rng = random.Random(20260824)
        values = []
        for _ in range(5000):
            bits = rng.randint(0, 64)
            v = rng.getrandbits(bits)
            values.append(v)
        # plus all boundary values 2**k and 2**k - 1 within range
        values.extend(v for k in range(0, 65) for v in (2**k, 2**k - 1) if v < 2**64)
        for v in values:
            enc = encode_uvarint(v)
            dec, consumed = decode_uvarint(enc)
            assert dec == v
            assert consumed == len(enc)


class TestSigned:
    def test_zigzag_vectors(self):
        assert [zigzag_encode(v) for v in (0, -1, 1, -2)] == [0, 1, 2, 3]
        assert [zigzag_decode(v) for v in (0, 1, 2, 3)] == [0, -1, 1, -2]

    def test_svarint_round_trip_5000(self):
        rng = random.Random(42)
        lo, hi = -(2**63), 2**63
        values = [rng.randint(lo, hi - 1) for _ in range(5000)]
        values.extend([lo, hi - 1, 0, -1, 1])
        for v in values:
            enc = encode_svarint(v)
            dec, consumed = decode_svarint(enc)
            assert dec == v
            assert consumed == len(enc)

    def test_negative_rejected_for_uvarint(self):
        with pytest.raises(ValueError):
            encode_uvarint(-1)


class TestMalformed:
    @pytest.mark.parametrize(
        "buf",
        [b"", b"\x80", b"\x80\x80", b"\x80\x80\x80\x80\x80"],
    )
    def test_truncated_raises(self, buf):
        with pytest.raises(VarintError):
            decode_uvarint(buf)

    def test_too_long_raises(self):
        with pytest.raises(VarintError):
            decode_uvarint(b"\x80" * 11 + b"\x00")

    def test_ten_continuation_bytes_is_truncated_not_overflow(self):
        # 10 bytes all carrying continuation bit: dangling bit at position 10.
        with pytest.raises(VarintError):
            decode_uvarint(b"\x80" * 10)

    def test_trailing_garbage_after_complete_varint_ok(self):
        assert decode_uvarint(b"\xac\x02\xff") == (300, 2)
